import pandas as pd, numpy as np
A=pd.read_csv('analysis_attribution.csv'); cols=['selectivity_effect_vs_refS','benefit_x2_activity','temperature_energy_gap','benefit_x10_stability','metal_cost_effect'];A['dominant']=A[cols].abs().idxmax(axis=1);print(A.dominant.value_counts().to_string());print('\nTop gap');print(A.nlargest(7,'gap_to_ref')[['rec_id','gap_to_ref','dominant']].to_string(index=False));print('\nBackward needing changes');B=pd.read_csv('analysis_backward.csv');print(B[['rec_id','base_cost','selectivity_needed','activity_multiplier_needed','metal_price_multiplier_needed']].to_string(index=False));R=pd.read_csv('analysis_rankings.csv');Q=R[R.metric.isin(['conversion','product_productivity'])];print('\nRank 2 metrics',len(Q),'agree',int(Q.agree.fillna(False).sum()),'disagree',int((Q.agree==False).sum()),'masked',Q.agree.isna().sum());print(Q[Q.agree==False][['paper','metric','leader','plant_choice','regret_usd_t']].to_string(index=False));print('regret mean/median/max',Q[Q.agree==False].regret_usd_t.mean(),Q[Q.agree==False].regret_usd_t.median(),Q[Q.agree==False].regret_usd_t.max())